package com.englishhero.reading.translation;
import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;import java.security.*;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
import com.englishhero.identity.*;import com.englishhero.reading.*;import com.englishhero.practice.review.PracticeReviewProperties;import com.englishhero.web.BusinessException;
import static com.englishhero.reading.translation.SelectionTranslationDtos.*;
@Service
public class SelectionTranslationService {
 private final SelectionTranslationMapper m;private final IdentityService identities;private final ReadingService reading;private final PracticeReviewProperties config;private final PracticeSelectionSource practice;private final EditorialReadingCatalog catalog;private final Clock clock;private final BaiduTranslationProperties baidu;
 public SelectionTranslationService(SelectionTranslationMapper m,IdentityService identities,ReadingService reading,PracticeReviewProperties config,Clock clock,BaiduTranslationProperties baidu,PracticeSelectionSource practice,EditorialReadingCatalog catalog){this.practice=practice;this.catalog=catalog;this.baidu=baidu;this.m=m;this.identities=identities;this.reading=reading;this.config=config;this.clock=clock;}
 private long actor(SessionPrincipal p){if(p==null)throw error(401,"UNAUTHENTICATED","请登录后使用实时翻译");identities.current(p);return p.userId();}
 static BusinessException error(int status,String code,String text){return new BusinessException(status,code,text);}
 static String normalized(String text){return text.replaceAll("\\s+"," ").strip();}
 static String hash(String text){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private static void uuid(String v){try{if(v==null||!UUID.fromString(v).toString().equals(v))throw new IllegalArgumentException();}catch(IllegalArgumentException e){throw BusinessException.invalid("requestId","请求编号无效");}}
 @Transactional(readOnly=true)public Task get(SessionPrincipal p,String id){return m.dto(actor(p),ArticleRules.id(id,"id"));}
 @Transactional(readOnly=true)public Task request(SessionPrincipal p,String request){long uid=actor(p);uuid(request);return m.sql().queryForList("SELECT translation_id FROM reading_selection_translation_request WHERE user_id=? AND request_id=?",Long.class,uid,request).stream().findFirst().map(id->m.dto(uid,id)).orElseThrow(()->error(404,"SELECTION_TRANSLATION_NOT_FOUND","翻译请求尚未确认"));}
 @Transactional(isolation=Isolation.READ_COMMITTED)public Task create(SessionPrincipal p,Input input){long uid=actor(p);if(input==null)throw BusinessException.invalid("text","请选择原文");uuid(input.requestId());long aid=ArticleRules.id(input.articleId(),"articleId"),vid=ArticleRules.id(input.versionId(),"versionId");String mode=input.mode()==null?"TRANSLATION":input.mode();if(!Set.of("TRANSLATION","GRAMMAR").contains(mode))throw BusinessException.invalid("mode","操作类型无效");long reserve="GRAMMAR".equals(mode)?10000:0;String text=normalized(ArticleContent.text(input.text(),"text",1000,true));if(java.util.regex.Pattern.compile("[A-Za-z]+").matcher(text).results().limit(2).count()<("GRAMMAR".equals(mode)?2:1))throw BusinessException.invalid("text","GRAMMAR".equals(mode)?"请选择两个以上英文单词":"请选择含英文字母的原文");
  var practiceVersion=practice.resolve(p,input);m.sql().queryForObject("SELECT id FROM identity_user WHERE id=? FOR UPDATE",Long.class,uid);identities.current(p);String scope=hash(("GRAMMAR".equals(mode)?"GRAMMAR\n":"BAIDU\n")+vid+"\n"+text),requestHash=hash(aid+"\n"+scope+(practice.present(input)?"\n"+Objects.toString(input.practiceAttemptId(),"")+"\n"+Objects.toString(input.paperAttemptId(),"")+"\n"+Objects.toString(input.slot(),""):""));
  var old=m.sql().queryForList("SELECT request_hash,translation_id FROM reading_selection_translation_request WHERE user_id=? AND request_id=?",uid,input.requestId());if(!old.isEmpty()){if(!requestHash.equals(old.getFirst().get("request_hash")))throw error(409,"SELECTION_TRANSLATION_CONFLICT","同一请求编号不能用于不同选文");return m.dto(uid,((Number)old.getFirst().get("translation_id")).longValue());}
  var version=practiceVersion==null?reading.version(p,input.articleId(),input.versionId()).version():practiceVersion;String full=normalized(version.content().paragraphs().stream().flatMap(par->par.sentences().stream()).map(s->s.text()).collect(java.util.stream.Collectors.joining(" ")));if(!full.contains(text))throw BusinessException.invalid("text","选文必须来自当前文章版本");
  var reuse=m.sql().queryForList("SELECT id FROM reading_selection_translation WHERE user_id=? AND scope_hash=? AND status IN ('QUEUED','RUNNING','SUCCEEDED') ORDER BY id DESC LIMIT 1",Long.class,uid,scope);if(!reuse.isEmpty())return remember(uid,input.requestId(),requestHash,reuse.getFirst());
  if("GRAMMAR".equals(mode)?!config.ready():!baidu.ready())throw error(503,"SELECTION_AI_UNAVAILABLE","GRAMMAR".equals(mode)?"语法解析暂不可用":"百度翻译尚未配置或暂不可用，本地查询仍可使用");if(m.sql().queryForObject("SELECT COUNT(*) FROM reading_selection_translation WHERE user_id=? AND status IN ('QUEUED','RUNNING')",Long.class,uid)>0)throw error(409,"SELECTION_TRANSLATION_ACTIVE","请先等待当前选文翻译完成");
  var now=clock.instant();var day=now.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate();if(m.sql().queryForObject("SELECT COUNT(*) FROM reading_selection_translation WHERE user_id=? AND budget_day=?",Long.class,uid,day)>=50)throw error(429,"SELECTION_TRANSLATION_LIMIT","今日实时翻译次数已用完");var last=m.sql().query("SELECT created_at FROM reading_selection_translation WHERE user_id=? ORDER BY id DESC LIMIT 1",(r,n)->r.getTimestamp(1).toInstant(),uid);if(!last.isEmpty()&&now.isBefore(last.getFirst().plusSeconds(2)))throw error(429,"SELECTION_TRANSLATION_LIMIT","请稍后再试");
  LocalDate quotaMonth=null;int characters=0;if("TRANSLATION".equals(mode)){quotaMonth=day.withDayOfMonth(1);characters=baidu.characters(text);m.sql().update("INSERT INTO reading_baidu_monthly_quota(month_start) VALUES(?) ON DUPLICATE KEY UPDATE month_start=VALUES(month_start)",quotaMonth);long usedCharacters=m.sql().queryForObject("SELECT used_characters FROM reading_baidu_monthly_quota WHERE month_start=? FOR UPDATE",Long.class,quotaMonth);if(characters>Math.max(0,baidu.getMonthlyCharacterLimit())-usedCharacters)throw error(429,"BAIDU_CHARACTER_QUOTA","本月百度翻译字符额度已用完");m.sql().update("UPDATE reading_baidu_monthly_quota SET used_characters=used_characters+? WHERE month_start=?",characters,quotaMonth);}else{m.sql().update("INSERT INTO practice_ai_daily_budget(budget_day) VALUES(?) ON DUPLICATE KEY UPDATE budget_day=VALUES(budget_day)",day);long used=m.sql().queryForObject("SELECT used_microusd FROM practice_ai_daily_budget WHERE budget_day=? FOR UPDATE",Long.class,day);if(used+reserve>config.getDailyBudgetMicrousd())throw error(429,"PRACTICE_AI_BUDGET","今日AI可用额度不足，部分额度可能仍在预留或待确认");m.sql().update("UPDATE practice_ai_daily_budget SET used_microusd=used_microusd+? WHERE budget_day=?",reserve,day);}
  long id=m.insert("INSERT INTO reading_selection_translation(user_id,article_id,version_id,scope_hash,source_text,status,model,budget_day,created_at,mode,reserved_microusd,source_characters,quota_month) VALUES(?,?,?,?,?,'QUEUED',?,?,?,?,?,?,?)",uid,aid,vid,scope,text,"GRAMMAR".equals(mode)?config.getModel():BaiduTranslationProperties.MODEL,day,java.sql.Timestamp.from(now),mode,reserve,characters==0?null:characters,quotaMonth);return remember(uid,input.requestId(),requestHash,id);
 }
 @Transactional(readOnly=true)public Reference reference(SessionPrincipal p,Input input){actor(p);if(input==null)throw BusinessException.invalid("text","请选择原文");String text=normalized(ArticleContent.text(input.text(),"text",1000,true));var version=practice.resolve(p,input);if(version==null)version=reading.version(p,input.articleId(),input.versionId()).version();String full=normalized(version.content().paragraphs().stream().flatMap(par->par.sentences().stream()).map(ArticleContent.Sentence::text).collect(java.util.stream.Collectors.joining(" ")));if(!full.contains(text))throw BusinessException.invalid("text","选文必须来自本轮原文");var reference=catalog.translation(version);for(var sentence:reference.sentences())if(normalized(sentence.sourceText()).equals(text))return new Reference(sentence.text(),reference.source());for(var paragraph:version.content().paragraphs())if(normalized(paragraph.sentences().stream().map(ArticleContent.Sentence::text).collect(java.util.stream.Collectors.joining(" "))).equals(text)){for(var translated:reference.paragraphs())if(translated.key().equals(paragraph.key()))return new Reference(translated.text(),reference.source());}return new Reference(null,null);}
 private Task remember(long uid,String request,String hash,long id){m.sql().update("INSERT INTO reading_selection_translation_request(user_id,request_id,request_hash,translation_id) VALUES(?,?,?,?)",uid,request,hash,id);return m.dto(uid,id);}
}
